const alert = $json.body ?? $json;
const ts = alert.timestamp;
return [{ json: {
  incident_id: alert.id,
  asset_id: alert.agent?.name ?? 'unknown-asset',
  start_time: ts,
  end_time: ts,
  family_hint: alert.decoder?.name === 'sshd' ? 'account' : 'unknown',
  features: {
    failed_login_count: Number(alert.data?.failed_login_count ?? 0),
    success_after_fail: Number(alert.data?.success_after_fail ?? 0)
  },
  evidence_sources: ['wazuh', String(alert.location ?? 'unknown-log').split('/').pop()],
  base_severity: Number(alert.rule?.level ?? 0),
  raw_refs: [`wazuh-alert:${alert.id}`],
  indicator: alert.data?.srcip ?? null
}}];

const decision = $json;
return [{ json: {
  status: 'notified',
  notification: `[SHADOW] Incident ${decision.incident_id}: risk ${decision.risk.display}/10, class ${decision.prediction.predicted_class}`,
  automation_state: decision.automation_state,
  strong_action_allowed: false,
  selected_playbook: decision.selected_playbook,
  audit: decision.audit,
  decision
}}];
